import React, { useEffect, useRef, useState } from 'react';
import { View, Image, StyleSheet, Animated, Easing, Text } from 'react-native';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from '../services/firebaseConfig';
import { LinearGradient } from 'expo-linear-gradient';

export default function SplashLogoScreen({ navigation }: any) {
  const opacity = useRef(new Animated.Value(0)).current;
  const progress = useRef(new Animated.Value(0)).current;
  const [percentage, setPercentage] = useState(0); // Estado para armazenar a porcentagem

  useEffect(() => {
    // Animação da logo (mantida igual)
    Animated.timing(opacity, {
      toValue: 1,
      duration: 600,
      useNativeDriver: true,
    }).start();

    // Animação da barra de progresso (mantida igual)
    const progressAnimation = Animated.timing(progress, {
      toValue: 1,
      duration: 1600,
      easing: Easing.inOut(Easing.ease),
      useNativeDriver: false,
    });

    // Atualiza a porcentagem a cada frame da animação
    const updatePercentage = () => {
      setPercentage(Math.floor(progress.value * 100));
    };

    // Adiciona um listener para atualizar a porcentagem
    progress.addListener(updatePercentage);

    // Inicia a animação
    progressAnimation.start();

    // Verificação de autenticação e navegação (mantida integralmente)
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setTimeout(() => {
        if (user && user.emailVerified) {
          navigation.replace('Inicio');
        } else {
          navigation.replace('Login');
        }
      }, 1800);
    });

    // Limpa o listener quando o componente for desmontado
    return () => {
      progress.removeListener(updatePercentage);
      unsubscribe();
    };
  }, [navigation, opacity, progress]);

  const widthInterpolate = progress.interpolate({
    inputRange: [0, 1],
    outputRange: ['0%', '100%'],
  });

  return (
    <View style={styles.container}>
      <Animated.Image
        source={require('../assets/logo.png')}
        style={[styles.logo, { opacity }]}
        resizeMode="contain"
      />
      {/* Texto que exibe a porcentagem */}
      <Text style={styles.percentageText}>{percentage}%</Text>
      {/* Barra de carregamento com efeito de partículas */}
      <View style={styles.progressBarContainer}>
        <Animated.View 
          style={[
            styles.progressBar, 
            { 
              width: widthInterpolate,
            }
          ]}
        >
          {/* Gradiente com brilhos */}
          <LinearGradient
            colors={['#0066FF', '#00CCFF', '#0066FF']} // Gradiente azul
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 0 }}
            style={styles.gradient}
          />
          {/* Efeito de brilho extra */}
          <Animated.View
            style={[
              styles.shineEffect,
              {
                opacity: progress.interpolate({
                  inputRange: [0, 0.5, 1],
                  outputRange: [0, 1, 0],
                }),
                transform: [
                  {
                    translateX: progress.interpolate({
                      inputRange: [0, 1],
                      outputRange: [-50, 250], // Move o brilho de um lado para o outro
                    }),
                  },
                ],
              },
            ]}
          />
        </Animated.View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#18182a',
    justifyContent: 'center',
    alignItems: 'center',
  },
  logo: {
    width: 180,
    height: 180,
    marginBottom: 20, // Reduzi a margem para caber a porcentagem
  },
  percentageText: {
    color: '#FFFFFF',
    fontSize: 18,
    fontWeight: 'bold',
    marginBottom: 10,
    textShadowColor: '#0066FF',
    textShadowOffset: { width: 0, height: 0 },
    textShadowRadius: 5,
  },
  progressBarContainer: {
    width: 200,
    height: 15, // Aumentei a altura para ficar mais grossa
    borderRadius: 7, // Aumentei o raio para manter a proporção
    backgroundColor: '#23243a',
    overflow: 'hidden',
    marginTop: 8,
    // Borda sutil como na imagem
    borderWidth: 1,
    borderColor: 'rgba(0, 122, 255, 0.3)',
  },
  progressBar: {
    height: '100%',
    borderRadius: 7,
    backgroundColor: 'rgba(0, 122, 255, 0.5)',
    position: 'relative',
  },
  gradient: {
    flex: 1,
    borderRadius: 7,
  },
  // Efeito de brilho extra
  shineEffect: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: 50,
    height: '100%',
    backgroundColor: 'rgba(255, 255, 255, 0.5)',
    borderRadius: 7,
  },
});